func ptrHazardousMaterial(p unsafe.Pointer, c int32) any {
	r := (*hazardousmaterial.HazardousMaterial)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Status))
	case 4:
		return &r.Code
	case 5:
		return &r.Name
	case 6:
		return &r.Description
	case 7:
		return (*string)(unsafe.Pointer(&r.Class))
	case 8:
		return &r.UNNumber
	case 9:
		return (*string)(unsafe.Pointer(&r.PackingGroup))
	case 10:
		return &r.SubsidiaryHazardClass
	case 11:
		return &r.ErgGuideNumber
	case 12:
		return &r.LabelCodes
	case 13:
		return &r.SpecialProvisions
	case 14:
		return &r.ProperShippingName
	case 15:
		return &r.HandlingInstructions
	case 16:
		return &r.EmergencyContact
	case 17:
		return &r.EmergencyContactPhoneNumber
	case 18:
		return &r.QuantityThreshold
	case 19:
		return &r.Rank
	case 20:
		return &r.PlacardRequired
	case 21:
		return &r.IsReportableQuantity
	case 22:
		return &r.MarinePollutant
	case 23:
		return &r.InhalationHazard
	case 24:
		return &r.Version
	case 25:
		return &r.CreatedAt
	case 26:
		return &r.UpdatedAt
	}
	return nil
}

